// cfg-hash: @@CFG_HASH@@  (support-config 변경 시 재생성 트리거)
package @@PACKAGE@@.support;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.Statement;
import java.util.Map;

import org.junit.jupiter.api.TestInfo;

/**
 * Black-Box 통합 테스트 공용 지원 유틸리티 (template-render v2 생성).
 *
 * <p>내부 애플리케이션 클래스를 import 하지 않는다. 순수 HTTP(RestAssured) + 직접 JDBC 만 사용한다.
 * 접속 정보 기본값은 prestep 환경 분석 산출물(support-config.json)에서 주입되며,
 * 시스템 프로퍼티로 외부 재정의 가능하다. 인증 헬퍼는 SUT마다 달라 여기 두지 않고
 * 각 테스트 클래스에 인증 카탈로그 패턴으로 렌더된다.</p>
 */
public final class BlackBoxSupport {

    private BlackBoxSupport() {
    }

    public static final String BASE_URL =
            System.getProperty("test.server.url", "@@SERVER_URL@@");
    public static final String WIREMOCK_URL =
            System.getProperty("test.wiremock.url", "@@WIREMOCK_URL@@");

    private static final String DB_URL =
            System.getProperty("test.db.url", "@@DB_URL@@");
    private static final String DB_USER =
            System.getProperty("test.db.user", "@@DB_USER@@");
    private static final String DB_PASSWORD =
            System.getProperty("test.db.password", "@@DB_PASSWORD@@");

    /** 병렬 안전: 매 호출마다 독립 Connection. */
    public static Connection getDbConnection() throws Exception {
        return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
    }

    /** 메서드명 기반 결정적 고유 ID (재실행 시 동일값). */
    public static String testId(TestInfo info) {
        return String.format("T%09d",
                Math.abs(info.getTestMethod().get().getName().hashCode()) % 1_000_000_000);
    }

    /**
     * testId → 결정적 숫자 seq. 실 데이터와 겹치지 않도록 오프셋을 더한다.
     * 오프셋 기본값은 support-config.json 의 idOffset 로 주입된다 — 대상 DB PK가
     * 32-bit INT 이면 32비트 한계 내(예: 1_000_000_000)로 설정할 것.
     */
    public static long testSeq(TestInfo info) {
        return @@ID_OFFSET@@L
                + (Math.abs(info.getTestMethod().get().getName().hashCode()) % 1_000_000_000L);
    }

    // ---- SQL 실행 ----------------------------------------------------------

    public static void executeSqlTemplate(String resourcePath, Map<String, String> params) {
        try (InputStream is = BlackBoxSupport.class.getClassLoader().getResourceAsStream(resourcePath)) {
            if (is == null) {
                throw new IllegalStateException("SQL resource not found: " + resourcePath);
            }
            String sql = new String(is.readAllBytes(), StandardCharsets.UTF_8);
            for (Map.Entry<String, String> e : params.entrySet()) {
                sql = sql.replace("${" + e.getKey() + "}", e.getValue());
            }
            executeSqlScript(sql);
        } catch (RuntimeException e) {
            throw e;
        } catch (Exception e) {
            throw new RuntimeException("SQL template execution failed: " + resourcePath, e);
        }
    }

    public static void executeSqlScript(String sql) {
        try (Connection conn = getDbConnection(); Statement stmt = conn.createStatement()) {
            StringBuilder current = new StringBuilder();
            for (String rawLine : sql.split("\n")) {
                String line = rawLine.trim();
                if (line.isEmpty() || line.startsWith("--")) {
                    continue;
                }
                current.append(line).append(' ');
                if (line.endsWith(";")) {
                    String stmtSql = current.toString().trim();
                    stmtSql = stmtSql.substring(0, stmtSql.length() - 1);
                    if (!stmtSql.isEmpty()) {
                        stmt.execute(stmtSql);
                    }
                    current.setLength(0);
                }
            }
            String tail = current.toString().trim();
            if (!tail.isEmpty()) {
                stmt.execute(tail);
            }
        } catch (Exception e) {
            throw new RuntimeException("SQL script execution failed", e);
        }
    }

    /** 단일 스칼라 조회(첫 컬럼). 없으면 null. */
    public static String queryScalar(String sql, Object... args) {
        try (Connection conn = getDbConnection();
             PreparedStatement ps = conn.prepareStatement(sql)) {
            for (int i = 0; i < args.length; i++) {
                ps.setObject(i + 1, args[i]);
            }
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) {
                    return rs.getString(1);
                }
                return null;
            }
        } catch (Exception e) {
            throw new RuntimeException("queryScalar failed: " + sql, e);
        }
    }
}

def synth_auth(auth, usage):
    """(메소드 자바 코드 or None, 종류: none|cookies|token, 추가 import 셋)"""
    pat = auth.get("pattern", "none")
    p = auth.get("params", {})
    if pat == "none":
        usage["catalog_auth"] += 1
        return None, "none", set()
    if pat == "custom":
        usage["custom_auth"] += 1
        ret = auth.get("returns", "cookies")
        rtype = "CookieFilter" if ret == "cookies" else "String"
        snippet = auth["customSnippet"]
        # T7: 저작 잔존 경로 — 위험 API 차단 (스텁 등록·리플렉션·프로세스 실행 금지)
        banned = ("stubFor", "WireMock.", "Runtime.getRuntime", "ProcessBuilder",
                  "Class.forName", "System.exit", "import ")
        hit = [b for b in banned if b in snippet]
        if hit:
            raise SpecError(f"auth.customSnippet 금지 API 사용: {hit} — 카탈로그 패턴을 쓰거나 스니펫에서 제거")
        body = "\n".join("        " + l for l in snippet.splitlines())
        return (f"    private {rtype} authenticate(Map<String, String> p) {{\n{body}\n    }}\n",
                ret, {"cookie"} if ret == "cookies" else set())
    if pat == "form-login":
        usage["catalog_auth"] += 1
        _ident(p["idParam"], "auth.params.idParam")
        extra = "".join(f'\n                .formParam("{esc_java(k)}", "{esc_java(v)}")'
                        for k, v in p.get("extraFormParams", {}).items())
        code = f"""    private CookieFilter authenticate(Map<String, String> p) {{
        CookieFilter cookies = new CookieFilter();
        given().filter(cookies).baseUri(BASE_URL)
                .contentType(ContentType.URLENC)
                .formParam("{esc_java(p['idField'])}", p.get("{p['idParam']}"))
                .formParam("{esc_java(p['pwField'])}", "{esc_java(p['password'])}"){extra}
        .when().post("{esc_java(p['loginPath'])}")
        .then().statusCode(200);
        return cookies;
    }}
"""
        return code, "cookies", {"cookie", "urlenc"}
    if pat == "session-form-sms":
        usage["catalog_auth"] += 1
        _ident(p["idParam"], "auth.params.idParam")
        _ident(p["certQueryParam"], "auth.params.certQueryParam")
        code = f"""    private CookieFilter authenticate(Map<String, String> p) {{
        CookieFilter cookies = new CookieFilter();
        given().filter(cookies).baseUri(BASE_URL)
                .header("X-Requested-With", "XMLHttpRequest")
                .contentType(ContentType.URLENC)
                .formParam("{esc_java(p['idField'])}", p.get("{p['idParam']}"))
                .formParam("{esc_java(p['pwField'])}", "{esc_java(p['password'])}")
        .when().post("{esc_java(p['loginPath'])}")
        .then().statusCode(200);
        String cert = queryScalar(
                "{esc_java(p['certQuery'])}", Long.parseLong(p.get("{p['certQueryParam']}")));
        if (cert == null) {{
            throw new IllegalStateException("certification not issued");
        }}
        given().filter(cookies).baseUri(BASE_URL)
                .header("X-Requested-With", "XMLHttpRequest")
                .contentType(ContentType.URLENC)
                .formParam("{esc_java(p['idField'])}", p.get("{p['idParam']}"))
                .formParam("{esc_java(p['pwField'])}", "{esc_java(p['password'])}")
                .formParam("{esc_java(p['certField'])}", cert)
        .when().post("{esc_java(p['smsPath'])}")
        .then().statusCode(200);
        return cookies;
    }}
"""
        return code, "cookies", {"cookie", "urlenc"}
    if pat == "bearer-token":
        usage["catalog_auth"] += 1
        body_json = json.dumps(p.get("bodyJson", {}), ensure_ascii=False)
        # ${X} 참조를 자바 문자열 연결로 치환
        java_body = '"' + esc_java(body_json) + '"'
        import re as _re
        java_body = _re.sub(r'\$\{(\w+)\}', lambda m: '" + p.get("%s") + "' % m.group(1), java_body)
        code = f"""    private String authenticate(Map<String, String> p) {{
        return given().baseUri(BASE_URL)
                .contentType(ContentType.JSON)
                .body({java_body})
        .when().post("{esc_java(p['loginPath'])}")
        .then().statusCode(200)
        .extract().jsonPath().getString("{esc_java(p['tokenJsonPath'])}");
    }}
"""
        return code, "token", {"urlenc"}
    raise ValueError(f"unknown auth pattern: {pat}")


