RES_KEYS = {"status", "headers", "jsonBody", "body", "fixedDelayMilliseconds"}


def synth_stub(stub, usage):
    if "rawJson" in stub:
        usage["raw_stub"] += 1
        return stub["rawJson"]
    usage["structured_stub"] += 1
    req = {k: v for k, v in stub["request"].items() if k in REQ_KEYS}

