import static org.hamcrest.Matchers.equalTo;

import java.util.Map;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import io.restassured.http.ContentType;

/**
 * Black-Box API Integration Test (template-rendered v2)
 *
 * @target-controller OwnerRestController (src/main/java/org/springframework/samples/petclinic/owner/OwnerRestController.java)
 * @target-api GET /api/owners/{ownerId}
 *
 * getOwner: ownerRepository.findById(ownerId) -> 200 Owner JSON, or 404 (ResponseEntity.notFound()) if absent.
 * auth: /api/** requires JWT Bearer (SecurityConfig); CustomUserDetailsService uses hardcoded admin/password creds, no DB fixture needed for auth.
 * ownerId (RED, DB_WHERE on findById) VTC rules applied: NULL, EMPTY, WHITE_SPACE, SPECIAL_CHAR, INVALID_FORMAT (from generate-vtc-from-red-params). LENGTH_EXCEEDED/SHRUNK excluded: ownerId is a numeric Integer PK with no DDL varchar length/boundary hint (skill itself did not emit these mutations).
 * VTC_ownerId_NULL and VTC_ownerId_EMPTY both render as pathParam ownerId="" against the fixed endpoint.path template (renderer has no raw-path-override / no-pathParam mode), so both are observably identical requests (empty path segment -> no route match -> 404); kept as two separate methods to satisfy 1:1 vtc-plan checklist even though the HTTP request is the same.
 * VTC_api_wrongMethod (405) and ATC missing/invalid-Authorization cases from the generic vtc-plan/API-level list are NOT included: the renderer binds HTTP method and the bearer-token Authorization header at the spec/class level (applied identically to every test in the class), so a different method or an intentionally missing/invalid Authorization header cannot be expressed per-test in this schema without a second spec/class. Not required by the Step2 test-plan checklist (throw_branches from analyze-auth-flow was empty), so omitted rather than forcing a raw/custom fallback.
 * No dbAssertions: GET is non-mutating, so the HTTP response body already fully verifies the persisted fixture state; a JDBC re-check would just restate the same setup values.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class OwnerGetByIdBlackBoxTest {

    private Map<String, String> seed(TestInfo info) {
        long seq = testSeq(info);
        return Map.of(
                "OWNER1", Long.toString(seq),
                "PET1", Long.toString(seq + 1),
                "VISIT1", Long.toString(seq + 2),
                "OWNER2", Long.toString(seq + 3),
                "OWNER3", Long.toString(seq + 4),
                "PET3", Long.toString(seq + 5),
                "VISIT3A", Long.toString(seq + 6),
                "VISIT3B", Long.toString(seq + 7),
                "OWNER_NOTFOUND", Long.toString(seq + 8));
    }

    private void arrange(Map<String, String> p) {
        executeSqlTemplate("sql/owner-get-by-id-teardown.sql", p);
        executeSqlTemplate("sql/owner-get-by-id-setup.sql", p);
    }

    private String authenticate(Map<String, String> p) {
        return given().baseUri(BASE_URL)
                .contentType(ContentType.JSON)
                .body("{\"username\": \"admin\", \"password\": \"password\"}")
        .when().post("/api/auth/login")
        .then().statusCode(200)
        .extract().jsonPath().getString("token");
    }

    @Test
    void NTC_getOwner_withPetAndVisit(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("ownerId", p.get("OWNER1"))
            .when()
                    .get("/api/owners/{ownerId}")
            .then()
                    .statusCode(200)
                    .body("firstName", equalTo("Nimbus"))
                    .body("lastName", equalTo("TestOwnerOne"))
                    .body("address", equalTo("100 Nimbus Ave"))
                    .body("city", equalTo("Springfield"))
                    .body("telephone", equalTo("5551234561"))
                    .body("pets.size()", equalTo(1))
                    .body("pets[0].name", equalTo("Rexy"))
                    .body("pets[0].birthDate", equalTo("2020-01-15"))
                    .body("pets[0].type.name", equalTo("cat"))
                    .body("pets[0].visits.size()", equalTo(1))
                    .body("pets[0].visits[0].description", equalTo("Annual checkup"))
                    .body("pets[0].visits[0].date", equalTo("2023-05-10"));
        } finally {
            executeSqlTemplate("sql/owner-get-by-id-teardown.sql", p);
        }
    }

    @Test
    void NTC_getOwner_noPets(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("ownerId", p.get("OWNER2"))
            .when()
                    .get("/api/owners/{ownerId}")
            .then()
                    .statusCode(200)
                    .body("firstName", equalTo("Nimbus"))
                    .body("lastName", equalTo("TestOwnerTwo"))
                    .body("address", equalTo("200 Nimbus Ave"))
                    .body("city", equalTo("Springfield"))
                    .body("telephone", equalTo("5551234562"))
                    .body("pets.size()", equalTo(0));
        } finally {
            executeSqlTemplate("sql/owner-get-by-id-teardown.sql", p);
        }
    }

    @Test
    void NTC_getOwner_petWithMultipleVisits(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("ownerId", p.get("OWNER3"))
            .when()
                    .get("/api/owners/{ownerId}")
            .then()
                    .statusCode(200)
                    .body("firstName", equalTo("Nimbus"))
                    .body("lastName", equalTo("TestOwnerThree"))
                    .body("pets.size()", equalTo(1))
                    .body("pets[0].name", equalTo("Buddy"))
                    .body("pets[0].type.name", equalTo("dog"))
                    .body("pets[0].visits.size()", equalTo(2))
                    .body("pets[0].visits[0].description", equalTo("Checkup A"))
                    .body("pets[0].visits[1].description", equalTo("Checkup B"));
        } finally {
            executeSqlTemplate("sql/owner-get-by-id-teardown.sql", p);
        }
    }

    @Test
    void ATC_ownerId_notFound(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("ownerId", p.get("OWNER_NOTFOUND"))
            .when()
                    .get("/api/owners/{ownerId}")
            .then()
                    .statusCode(404);;
        } finally {
            executeSqlTemplate("sql/owner-get-by-id-teardown.sql", p);
        }
    }

    @Test
    void VTC_ownerId_NULL(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("ownerId", "")
            .when()
                    .get("/api/owners/{ownerId}")
            .then()
                    .statusCode(404);;
        } finally {
            executeSqlTemplate("sql/owner-get-by-id-teardown.sql", p);
        }
    }

    @Test
    void VTC_ownerId_EMPTY(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("ownerId", "")
            .when()
                    .get("/api/owners/{ownerId}")
            .then()
                    .statusCode(404);;
        } finally {
            executeSqlTemplate("sql/owner-get-by-id-teardown.sql", p);
        }
    }

    @Test
    void VTC_ownerId_WHITE_SPACE(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("ownerId", "   ")
            .when()
                    .get("/api/owners/{ownerId}")
            .then()
                    .statusCode(400);;
        } finally {
            executeSqlTemplate("sql/owner-get-by-id-teardown.sql", p);
        }
    }

    @Test
    void VTC_ownerId_SPECIAL_CHAR(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("ownerId", "'; DROP TABLE --")
            .when()
                    .get("/api/owners/{ownerId}")
            .then()
                    .statusCode(400);;
        } finally {
            executeSqlTemplate("sql/owner-get-by-id-teardown.sql", p);
        }
    }

    @Test
    void VTC_ownerId_INVALID_FORMAT(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("ownerId", "NOT_A_NUMBER")
            .when()
                    .get("/api/owners/{ownerId}")
            .then()
                    .statusCode(400);;
        } finally {
            executeSqlTemplate("sql/owner-get-by-id-teardown.sql", p);
        }
    }
}

